"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a branding iron Trail', 'author': 'Signature original', 'genre': 'Outlaw Legends', 'chapters': [{'n': 1, 'title': 'Dust on the Wind', 'text': "the sheriff was the first to offer a meal and the news. 'the outlaw Black Bart means to take it all,' the sheriff said. 'The water, the grazing, the town. Unless somebody stands up.' Jake Calloway ate slowly. Standing up was a habit.\n\nJake Calloway slept with a branding iron under the pillow and one eye open. the frontier makes family — out here, that's not a saying. It's the whole law.\n\nJake Calloway rode into Copper Basin at sundown, with a branding iron in the saddlebag and dust in every seam. The town had the feel of a held breath — and the reason was posted on every wall: the outlaw Black Bart's notice, claiming the valley."}, {'n': 2, 'title': 'The Claim', 'text': "the sheriff stood with Jake Calloway — and then the blacksmith, and the schoolteacher, and one by one half the town. 'We know Jake Calloway's word,' the sheriff said. It wasn't much. It was everything.\n\nThe judge — the outlaw Black Bart's judge — set a hearing for Friday. Three days to prove a branding iron real, with the outlaw Black Bart's men watching every step. Jake Calloway smiled the thin smile of someone holding four aces.\n\nThursday night they came with fire. The livery burned, and a branding iron's copies with it — but Jake Calloway had the original where fire couldn't reach. the outlaw Black Bart had played the last card. Friday would tell."}, {'n': 3, 'title': 'High Noon', 'text': "the outlaw Black Bart's claim died that afternoon, in public, on the record. Copper Basin exhaled. the sheriff bought the drinks. Jake Calloway drank one, slow, tasting justice. It tasted like dust and sweet water.\n\nWhat happened next took four seconds and would be told for forty years. When the dust settled, the outlaw Black Bart's gunmen were down — winged, not killed; Jake Calloway never shot to kill if winging would do — and the outlaw Black Bart stood alone, empty-handed.\n\nThe hearing went ahead anyway, because Jake Calloway insisted on it. Law, not guns. a branding iron was examined, the witness testified, the seal was verified. The judge — even the outlaw Black Bart's judge — couldn't lie with the whole town watching."}, {'n': 4, 'title': 'The Drive', 'text': "the outlaw Black Bart's rustlers hit them at the canyon — the last play of a losing hand. The fight was short and decisive: the town rode together, and together is a word the outlaw Black Bart never understood.\n\nthe outlaw Black Bart wasn't done — the breed never is. The cattle were driven off in the night, the water rights challenged, the railroad brought in. Copper Basin needed more than a verdict; it needed a future.\n\nJake Calloway organized the drive: every ranch, every hand, moving the herds to the railhead themselves, cutting out the outlaw Black Bart's middlemen. the sheriff rode drag. a branding iron — the deed — rode in Jake Calloway's breast pocket, the reason for it all."}, {'n': 5, 'title': 'Home Range', 'text': "the outlaw Black Bart was last seen heading east, smaller in the distance. Copper Basin didn't gloat. The frontier doesn't gloat; it just keeps the water clean and the word good.\n\nBut Jake Calloway stayed through the winter, helping the sheriff mend fences, teaching the kids to read sign, being — for a while — part of Copper Basin instead of just its defender. It suited them.\n\nJake Calloway was offered the sheriff's star, the mayor's office, and three ranches. Jake Calloway took none of them. 'I ride,' Jake Calloway said, which explained everything and nothing, the way true things do."}, {'n': 6, 'title': 'Sundown', 'text': "Spring came, and Jake Calloway rode out with the thaw, a branding iron's story told and retold in the saloon. the sheriff watched them go from the porch, and didn't wave — waving is for endings, and this wasn't one.\n\nJake Calloway rides somewhere west, where the map goes blank. There are always more valleys, more villains, more folks needing one person to stand. The frontier doesn't end. It just moves.\n\nthe sheriff keeps a room ready, and the kettle on, and the news of Copper Basin in letters. 'Come home when the trail allows,' every letter ends. The trail always allows, eventually."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

